 210: LossyDctDecoder_execute (
 211:     void* (*alloc_fn) (size_t), void (*free_fn) (void*), LossyDctDecoder* d)
 212: {
 213:     exr_result_t         rv;
 214:     int                  numComp = d->_channel_decode_data_count;
 215:     DctCoderChannelData* chanData[3];
 216:     int                  lastNonZero = 0;
 217:     int                  numBlocksX  = (int) (ceilf ((float) d->_width / 8.0f));
 218:     int                  numBlocksY = (int) (ceilf ((float) d->_height / 8.0f));
 219:     int                  leftoverX  = d->_width - (numBlocksX - 1) * 8;
 220:     int                  leftoverY  = d->_height - (numBlocksY - 1) * 8;
 221: 
 222:     int numFullBlocksX = (int) (floorf ((float) d->_width / 8.0f));
 223: 
 224:     uint16_t* currAcComp = (uint16_t*) (d->_packedAc);
 225:     uint16_t* acCompEnd  = (uint16_t*) (d->_packedAcEnd);
 226:     uint16_t* currDcComp[3];
 227:     uint8_t*  rowBlockHandle;
 228:     uint16_t* rowBlock[3];
 229: 
 230:     for (int chan = 0; chan < numComp; ++chan)
 231:     {
 232:         chanData[chan] = d->_channel_decode_data[chan];
 233:     }
 234: 
 235:     //
 236:     // Allocate a temp aligned buffer to hold a rows worth of full
 237:     // 8x8 half-float blocks
 238:     //
 239: 
 240:     rowBlockHandle = alloc_fn (
 241:         (size_t) numComp * (size_t) numBlocksX * 64 * sizeof (uint16_t) +
 242:         _SSE_ALIGNMENT);
 243:     if (!rowBlockHandle) return EXR_ERR_OUT_OF_MEMORY;
 244: 
 245:     rowBlock[0] = (uint16_t*) rowBlockHandle;
 246: 
 247:     for (int i = 0; i < _SSE_ALIGNMENT; ++i)
 248:     {
 249:         if (((uintptr_t) (rowBlockHandle + i) & _SSE_ALIGNMENT_MASK) == 0)
 250:             rowBlock[0] = (uint16_t*) (rowBlockHandle + i);
 251:     }
 252: 
 253:     for (int comp = 1; comp < numComp; ++comp)
 254:         rowBlock[comp] = rowBlock[comp - 1] + numBlocksX * 64;
 255: 
 256:     //
 257:     // Pack DC components together by common plane, so we can get
 258:     // a little more out of differencing them. We'll always have
 259:     // one component per block, so we can computed offsets.
 260:     //
