 660: // a half buffer. The half block should
 661: // be the full 8x8 block (in zig-zag order
 662: // still), not the first AC component.
 663: //
 664: // currAcComp is advanced as bytes are decoded.
 665: //
 666: // This returns the index of the last non-zero
 667: // value in the buffer - with the index into zig zag
 668: // order data. If we return 0, we have DC only data.
 669: //
 670: // This is assuminging that halfZigBlock is zero'ed
 671: // prior to calling
 672: //
 673: exr_result_t
 674: LossyDctDecoder_unRleAc (
 675:     LossyDctDecoder* d,
 676:     int*             lastNonZero,
 677:     uint16_t**       currAcComp,
 678:     uint16_t*        packedAcEnd,
 679:     uint16_t*        halfZigBlock)
 680: {
 681:     //
 682:     // Un-RLE the RLE'd blocks. If we find an item whose
 683:     // high byte is 0xff, then insert the number of 0's
 684:     // as indicated by the low byte.
 685:     //
 686:     // Otherwise, just copy the number verbatim.
 687:     //
 688:     int       dctComp = 1;
 689:     uint16_t* acComp  = *currAcComp;
 690:     uint16_t  val;
 691:     int       lnz      = 0;
 692:     uint64_t  ac_count = 0;
 693: 
 694:     //
 695:     // Start with a zero'ed block, so we don't have to
 696:     // write when we hit a run symbol
 697:     //
 698: 
 699:     while (dctComp < 64)
 700:     {
 701:         if (acComp >= packedAcEnd) { return EXR_ERR_CORRUPT_CHUNK; }
 702:         val = *acComp;
 703:         if (val == 0xff00)
 704:         {
 705:             //
 706:             // End of block
 707:             //
 708: 
 709:             dctComp = 64;
 710:         }
 711:         else if ((val >> 8) == 0xff)
 712:         {
 713:             //
 714:             // Run detected! Insert 0's.
 715:             //
 716:             // Since the block has been zeroed, just advance the ptr
 717:             //
 718: 
 719:             dctComp += val & 0xff;
 720:         }
 721:         else
 722:         {
 723:             //
 724:             // Not a run, just copy over the value
 725:             //
 726:             lnz                   = dctComp;
 727:             halfZigBlock[dctComp] = val;
 728: 
 729:             dctComp++;
 730:         }
 731: 
 732:         ac_count++;
 733:         acComp++;
 734:     }
 735: 
 736:     d->_packedAcCount += ac_count;
 737:     *lastNonZero = lnz;
 738:     *currAcComp  = acComp;
 739:     return EXR_ERR_SUCCESS;
 740: }
